// @ts-nocheck
// Geometry/icons from approved v5; see provenance.json.
/* Pure SVG charts. Values and scales are shared by all visible/offscreen columns. */
export const charts=(()=>{
 const fa=n=>String(n).replace(/\d/g,d=>'۰۱۲۳۴۵۶۷۸۹'[d]).replace(/\./g,'٫');
 const num=(n,sign=false)=>n==null?'—':fa((sign&&n>0?'+':n<0?'−':'')+Math.abs(n).toFixed(Number.isInteger(n)?0:1));
 const text=(v,x,y,cls='chart-value',fill='var(--ink)',extra='')=>`<text x="${x}" y="${y}" ${extra.includes('text-anchor')?'':'text-anchor="middle"'} direction="ltr" class="${cls}" fill="${fill}" ${extra}>${v}</text>`;
 const caption=(title,unit,sub='',layout={})=>layout.compact?`<g class="metric-caption"><foreignObject x="${-layout.captionWidth}" y="0" width="${layout.captionWidth}" height="44"><div xmlns="http://www.w3.org/1999/xhtml" class="metric-label" dir="rtl"><span>${title}</span>${unit?`<span class="metric-label-unit" dir="ltr">${unit}</span>`:''}${sub?`<span class="metric-label-sub">${sub}</span>`:''}</div></foreignObject></g>`:`<g class="metric-caption"><text y="14" text-anchor="start" class="chart-caption">${title}</text><text y="27" text-anchor="end" class="chart-caption unit">${unit}</text>${sub?`<text y="39" text-anchor="start" class="chart-caption sub">${sub}</text>`:''}</g>`;
 const wrap=(body,w,h,key,title)=>`<svg class="chart-row" data-metric="${key}" viewBox="0 0 ${w} ${h}" style="height:${h}px" role="img" aria-label="${title}">${body}</svg>`;
 const domain=vals=>{vals=vals.filter(Number.isFinite);const lo=vals.length?Math.min(...vals):0,hi=vals.length?Math.max(...vals):0,pad=Math.max(2,(hi-lo)*.12);return {low:lo-pad,high:hi+pad};};
 const y=(v,d,t,b)=>t+(d.high-v)/(d.high-d.low)*(b-t);
 const color=(p,k)=>p.hazards?.includes(k)?'var(--red)':p[k]>0?'var(--warm)':p[k]<0?'var(--cool)':'var(--secondary)';
 let uid=0;
 function parts(points,xs,key,d,top,bottom){
  const ordered=points.map((p,i)=>({p,x:xs[i],v:p[key]})).sort((a,b)=>a.x-b.x),out=[],chunk=[];
  const evalY=(c,t)=>(1-t)**3*c[0][1]+3*(1-t)**2*t*c[1][1]+3*(1-t)*t*t*c[2][1]+t**3*c[3][1];
  function cut(c,t){const l=(a,b)=>[a[0]+(b[0]-a[0])*t,a[1]+(b[1]-a[1])*t],a=l(c[0],c[1]),b=l(c[1],c[2]),d=l(c[2],c[3]),e=l(a,b),f=l(b,d),g=l(e,f);return [[c[0],a,e,g],[g,f,d,c[3]]];}
  function flush(){if(chunk.length<2){chunk.length=0;return;}const vals=chunk.map(p=>y(p.v,d,top,bottom)),ds=chunk.slice(1).map((p,i)=>(vals[i+1]-vals[i])/(p.x-chunk[i].x));const slopes=chunk.map((p,i)=>i===0?ds[0]:i===chunk.length-1?ds.at(-1):ds[i-1]*ds[i]<=0?0:2*ds[i-1]*ds[i]/(ds[i-1]+ds[i]));
   for(let i=0;i<chunk.length-1;i++){const a=chunk[i],b=chunk[i+1],dx=b.x-a.x,c=[[a.x,vals[i]],[a.x+dx/3,vals[i]+slopes[i]*dx/3],[b.x-dx/3,vals[i+1]-slopes[i+1]*dx/3],[b.x,vals[i+1]]];if(a.v*b.v<0){let lo=0,hi=1,zy=y(0,d,top,bottom);for(let j=0;j<28;j++){const m=(lo+hi)/2;if((evalY(c,m)>zy)===(c[0][1]>zy))lo=m;else hi=m;}const [l,r]=cut(c,(lo+hi)/2);out.push({c:l,warm:a.v>0},{c:r,warm:b.v>0});}else out.push({c,warm:(a.v+b.v)/2>0});}chunk.length=0;}
  for(const p of ordered){if(Number.isFinite(p.v))chunk.push(p);else flush();}flush();return out;
 }
 function temperature(points,xs,w,{key='felt',range=false,height=112,...layout}={}){
  const top=layout.compact?(layout.mobileCompact&&!range?46:64):range?54:42,bottom=range?(layout.compact?height-29:128):height-14,d=domain(points.flatMap(p=>range?[p[key],p.min,p.max]:[p[key]])),id=++uid;
  let body=`<defs><linearGradient id="w${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--warm)" stop-opacity=".2"/><stop offset="1" stop-color="var(--warm)" stop-opacity=".025"/></linearGradient><linearGradient id="c${id}" x1="0" y1="0" x2="0" y2="1"><stop stop-color="var(--cool)" stop-opacity=".18"/><stop offset="1" stop-color="var(--cool)" stop-opacity=".02"/></linearGradient></defs>`;
  for(const a of parts(points,xs,key,d,top,bottom)){const c=a.c,path=`M${c[0]}C${c[1]} ${c[2]} ${c[3]}`,col=a.warm?'warm':'cool';body+=`<path d="${path}L${c[3][0]},${bottom+7}L${c[0][0]},${bottom+7}Z" fill="url(#${a.warm?'w':'c'}${id})"/><path d="${path}" fill="none" stroke="var(--${col})" stroke-width="${range?1.7:2.4}"/>`;}
  points.forEach((p,i)=>{const x=xs[i],v=p[key];if(!Number.isFinite(v)){body+=text('—',x,(top+bottom)/2,'no-data');return;}const py=y(v,d,top,bottom),col=color(p,key);
   if(range&&Number.isFinite(p.min)&&Number.isFinite(p.max)&&p.min!==p.max){const ymin=y(p.min,d,top,bottom),ymax=y(p.max,d,top,bottom);body+=`<path d="M${x},${ymax}V${ymin}M${x-3},${ymax}H${x+3}M${x-3},${ymin}H${x+3}" fill="none" stroke="${col}" stroke-width="1.1" opacity=".7" data-range="${p.min},${p.max}"/>`;body+=text(num(p.max,true),x,Math.min(ymax-7,py-17),'chart-value range',color({actual:p.max},'actual'))+text(num(p.min,true),x,Math.max(ymin+13,py+18),'chart-value range',color({actual:p.min},'actual'))+text(num(v,true),x+10,py+4,'chart-value',col,'text-anchor="start"');}
   else body+=text(num(v,true),x,py-10,range?'chart-value':'chart-value temperature',col);
   body+=`<circle cx="${x}" cy="${py}" r="${range?3:4}" fill="${range?col:'var(--solid)'}" stroke="${col}" stroke-width="${range?1:2.2}" data-value="${v}" data-point="${p.id}"/>`;
  });return wrap(body+caption(range?'دمای واقعی':'دمای حسی','°C',range?'کمینه / بیشینه':'',layout),w,height,key,range?'دمای واقعی و کمینه تا بیشینه':'دمای حسی');
 }
 function stems(points,xs,w,key,max,height=86,layout={}){const base=height-7;let body='';points.forEach((p,i)=>{const x=xs[i],v=p[key],col=p.hazards?.includes(key)?'var(--red)':'var(--wind)';if(!Number.isFinite(v)){body+=text('—',x,57,'no-data');return;}const py=base-v/max*40;body+=`<path d="M${x} ${base}V${py}" stroke="${col}" stroke-width="1.5" data-stem-value="${v}"/><path d="M${x} ${py-4.5}l4.5 4.5-4.5 4.5-4.5-4.5Z" fill="var(--solid)" stroke="${col}" stroke-width="1.6"/>${text(num(v),x,py-10,'chart-value',col)}`;});return wrap(body+caption(key==='gust'?'تندباد':'باد','km/h','',layout),w,height,key,key==='gust'?'تندباد':'باد');}
 function rain(points,xs,w,height=70,layout={}){const max=Math.max(1,...points.map(p=>Number.isFinite(p.rain)?p.rain:0)),base=height-8;let b='';points.forEach((p,i)=>{const x=xs[i],v=p.rain;if(!Number.isFinite(v)){b+=text('—',x,47,'no-data');return;}const bh=v/max*24,col=p.hazards?.includes('rain')?'var(--red)':'var(--rain)';if(v>0)b+=`<rect x="${x-13}" y="${base-bh}" width="26" height="${bh}" rx="1.4" fill="${col}" opacity=".8" data-rain-value="${v}"/>`;b+=text(num(v),x,base-bh-9,'chart-value',p.hazards?.includes('rain')?'var(--red)':'var(--ink)');});return wrap(b+caption('بارش','mm','',layout),w,height,'rain','مقدار بارش');}
 function small(points,xs,w,key,height,layout={}){const max=Math.max(1,...points.map(p=>p.visibility).filter(Number.isFinite));let b='';points.forEach((p,i)=>{const x=xs[i],v=p[key],col=p.hazards?.includes(key)?'var(--red)':'var(--accent)';if(!Number.isFinite(v)){b+=text('—',x,40,'no-data');return;}if(key==='direction'){b+=`<g transform="translate(${x-9} 29) rotate(${(v+180)%360} 9 9)" stroke="var(--ink)" fill="none" stroke-width="1.5" stroke-linecap="round"><title>باد از ${fa(v)} درجه</title><path d="M9 16V2m-4 4 4-4 4 4"/></g>`;}else if(key==='humidity'){b+=`<rect x="${x-20}" y="45" width="40" height="4" rx="2" fill="var(--border)"/><rect x="${x-20}" y="45" width="${40*v/100}" height="4" rx="2" fill="${col}" opacity=".75"/>${text(num(v)+'٪',x,37,'chart-value small')}`;}else b+=`<path d="M${x-13} 47h26" stroke="var(--border)" stroke-width="3" stroke-linecap="round"/><path d="M${x-13} 47h${26*v/max}" stroke="${col}" stroke-width="3" stroke-linecap="round" opacity=".65"/>${text(num(v),x,36,'chart-value small')}`;});return wrap(b+caption({direction:'جهت باد',humidity:'رطوبت',visibility:'دید'}[key],{direction:'',humidity:'%',visibility:'km'}[key],'',layout),w,height,key,key);}
 function freezing(points,xs,w,height=78,layout={}){const d=domain(points.map(p=>p.freezing)),top=layout.compact?56:39,bottom=height-9;let b='',last='';points.forEach((p,i)=>{const x=xs[i],v=p.freezing;if(!Number.isFinite(v)){last='';b+=text('—',x,54,'no-data');return;}const py=y(v,d,top,bottom);if(last)b+=`<path d="M${last}L${x},${py}" fill="none" stroke="var(--accent)" stroke-width="1.5" opacity=".85"/>`;last=`${x},${py}`;b+=`<circle cx="${x}" cy="${py}" r="2.8" fill="var(--solid)" stroke="var(--accent)" stroke-width="1.4"/>${text(num(v),x,py-9,'chart-value small')}`;});return wrap(b+caption('تراز صفر درجه','m','',layout),w,height,'freezing','تراز صفر درجه');}
 function rows(p,x,w,experts=false,exporting=false,layout={}){const max=Math.max(10,...p.flatMap(a=>[a.wind,a.gust]).filter(Number.isFinite));let h=temperature(p,x,w,{height:layout.compact?(layout.mobileCompact?100:118):exporting?125:112,...layout})+stems(p,x,w,'wind',max,layout.compact?94:86,layout)+rain(p,x,w,layout.compact?78:70,layout);if(experts)h+=expertRows(p,x,w,layout);return h;}
 function expertRows(p,x,w,layout={}){const max=Math.max(10,...p.flatMap(a=>[a.wind,a.gust]).filter(Number.isFinite));return temperature(p,x,w,{key:'actual',range:true,height:layout.compact?142:157,...layout})+stems(p,x,w,'gust',max,layout.compact?94:86,layout)+small(p,x,w,'direction',57,layout)+small(p,x,w,'humidity',60,layout)+small(p,x,w,'visibility',60,layout)+freezing(p,x,w,layout.compact?90:78,layout);}
 return {fa,num,domain,y,temperature,stems,rain,small,freezing,rows,expertRows};
})();
